// StrictServerInterface represents all server handlers.
type StrictServerInterface interface {
	// GetBackups Database backups and the latest backup/scrub status
	// (GET /admin/backups)
	GetBackups(ctx context.Context, request GetBackupsRequestObject) (GetBackupsResponseObject, error)
	// RunBackup Back up the database now
	// (POST /admin/backups)
	RunBackup(ctx context.Context, request RunBackupRequestObject) (RunBackupResponseObject, error)
	// ListMasterBooks Browse the master store (every book the server holds)
	// (GET /admin/books)
	ListMasterBooks(ctx context.Context, request ListMasterBooksRequestObject) (ListMasterBooksResponseObject, error)
	// TrashBook Move a book to the Trash (hidden everywhere; purged after 30 days)
	// (DELETE /admin/books/{bookId})
	TrashBook(ctx context.Context, request TrashBookRequestObject) (TrashBookResponseObject, error)
	// GetMasterBook One master-store book with its distributions
	// (GET /admin/books/{bookId})
	GetMasterBook(ctx context.Context, request GetMasterBookRequestObject) (GetMasterBookResponseObject, error)
	// PurgeBook Permanently delete one trashed book and its files now
	// (POST /admin/books/{bookId}/purge)
	PurgeBook(ctx context.Context, request PurgeBookRequestObject) (PurgeBookResponseObject, error)
	// RestoreBook Restore a book from the Trash
	// (POST /admin/books/{bookId}/restore)
	RestoreBook(ctx context.Context, request RestoreBookRequestObject) (RestoreBookResponseObject, error)
	// CreateDistribution Make a master-store book visible to a group or a user
	// (POST /admin/distributions)
	CreateDistribution(ctx context.Context, request CreateDistributionRequestObject) (CreateDistributionResponseObject, error)
	// RevokeDistribution Revoke a distribution
	// (DELETE /admin/distributions/{distributionId})
	RevokeDistribution(ctx context.Context, request RevokeDistributionRequestObject) (RevokeDistributionResponseObject, error)
	// ListGroups Groups
	// (GET /admin/groups)
	ListGroups(ctx context.Context, request ListGroupsRequestObject) (ListGroupsResponseObject, error)
	// CreateGroup Create a group
	// (POST /admin/groups)
	CreateGroup(ctx context.Context, request CreateGroupRequestObject) (CreateGroupResponseObject, error)
	// DeleteGroup Delete a group (the built-in Public group cannot be deleted)
	// (DELETE /admin/groups/{groupId})
	DeleteGroup(ctx context.Context, request DeleteGroupRequestObject) (DeleteGroupResponseObject, error)
	// RemoveGroupMember Remove a user from a group
	// (DELETE /admin/groups/{groupId}/members/{userId})
	RemoveGroupMember(ctx context.Context, request RemoveGroupMemberRequestObject) (RemoveGroupMemberResponseObject, error)
	// AddGroupMember Add a user to a group
	// (PUT /admin/groups/{groupId}/members/{userId})
	AddGroupMember(ctx context.Context, request AddGroupMemberRequestObject) (AddGroupMemberResponseObject, error)
	// RunIntegrityCheck Re-hash every library file against its stored checksum now
	// (POST /admin/integrity-check)
	RunIntegrityCheck(ctx context.Context, request RunIntegrityCheckRequestObject) (RunIntegrityCheckResponseObject, error)
	// ScanLibrary Rescan the library folder now
	// (POST /admin/library/scan)
	ScanLibrary(ctx context.Context, request ScanLibraryRequestObject) (ScanLibraryResponseObject, error)
	// AdminRevokeSession Revoke any user's session
	// (DELETE /admin/sessions/{sessionId})
	AdminRevokeSession(ctx context.Context, request AdminRevokeSessionRequestObject) (AdminRevokeSessionResponseObject, error)
	// ListSignupRequests Sign-up requests (moderation inbox)
	// (GET /admin/signup-requests)
	ListSignupRequests(ctx context.Context, request ListSignupRequestsRequestObject) (ListSignupRequestsResponseObject, error)
	// ApproveSignupRequest Approve a sign-up (user becomes active and joins Public)
	// (POST /admin/signup-requests/{requestId}/approve)
	ApproveSignupRequest(ctx context.Context, request ApproveSignupRequestRequestObject) (ApproveSignupRequestResponseObject, error)
	// DenySignupRequest Deny a sign-up
	// (POST /admin/signup-requests/{requestId}/deny)
	DenySignupRequest(ctx context.Context, request DenySignupRequestRequestObject) (DenySignupRequestResponseObject, error)
	// EmptyTrash Permanently delete everything in the Trash
	// (POST /admin/trash/empty)
	EmptyTrash(ctx context.Context, request EmptyTrashRequestObject) (EmptyTrashResponseObject, error)
	// ListUsers Users
	// (GET /admin/users)
	ListUsers(ctx context.Context, request ListUsersRequestObject) (ListUsersResponseObject, error)
	// PatchUser Change a user's status, role, quota or notice (a reason is required)
	// (PATCH /admin/users/{userId})
	PatchUser(ctx context.Context, request PatchUserRequestObject) (PatchUserResponseObject, error)
	// Login Log in with username + password
	// (POST /auth/login)
	Login(ctx context.Context, request LoginRequestObject) (LoginResponseObject, error)
	// Logout End the current device session
	// (POST /auth/logout)
	Logout(ctx context.Context, request LogoutRequestObject) (LogoutResponseObject, error)
	// RefreshTokens Exchange a refresh token for a new token pair (rotating)
	// (POST /auth/refresh)
	RefreshTokens(ctx context.Context, request RefreshTokensRequestObject) (RefreshTokensResponseObject, error)
	// Signup Request an account (creates a pending user awaiting admin approval)
	// (POST /auth/signup)
	Signup(ctx context.Context, request SignupRequestObject) (SignupResponseObject, error)
	// ConfirmTotp Confirm TOTP enrollment; returns the 10 one-time recovery codes
	// (POST /auth/totp/confirm)
	ConfirmTotp(ctx context.Context, request ConfirmTotpRequestObject) (ConfirmTotpResponseObject, error)
	// EnrollTotp Start TOTP enrollment (returns secret + otpauth URI)
	// (POST /auth/totp/enroll)
	EnrollTotp(ctx context.Context, request EnrollTotpRequestObject) (EnrollTotpResponseObject, error)
	// VerifyTotp Complete login with a TOTP code or a recovery code
	// (POST /auth/totp/verify)
	VerifyTotp(ctx context.Context, request VerifyTotpRequestObject) (VerifyTotpResponseObject, error)
	// GetAuthor Author page (books visible to me)
	// (GET /authors/{personId})
	GetAuthor(ctx context.Context, request GetAuthorRequestObject) (GetAuthorResponseObject, error)
	// GetBook Book detail (files, chapters, my progress)
	// (GET /books/{bookId})
	GetBook(ctx context.Context, request GetBookRequestObject) (GetBookResponseObject, error)
	// GetBookCover Cover image (resized variant)
	// (GET /books/{bookId}/cover)
	GetBookCover(ctx context.Context, request GetBookCoverRequestObject) (GetBookCoverResponseObject, error)
	// GetBookFile Original audio file (supports HTTP Range)
	// (GET /books/{bookId}/files/{fileId})
	GetBookFile(ctx context.Context, request GetBookFileRequestObject) (GetBookFileResponseObject, error)
	// CreateStreamUrl Signed, short-lived stream URLs for casting targets
	// (POST /books/{bookId}/stream-url)
	CreateStreamUrl(ctx context.Context, request CreateStreamUrlRequestObject) (CreateStreamUrlResponseObject, error)
	// RegisterPush Register this device for push notifications
	// (POST /devices/push-subscription)
	RegisterPush(ctx context.Context, request RegisterPushRequestObject) (RegisterPushResponseObject, error)
	// UnregisterPush Stop push notifications for a device
	// (DELETE /devices/push-subscription/{deviceId})
	UnregisterPush(ctx context.Context, request UnregisterPushRequestObject) (UnregisterPushResponseObject, error)
	// GetHealth Liveness check (used by container healthchecks)
	// (GET /health)
	GetHealth(ctx context.Context, request GetHealthRequestObject) (GetHealthResponseObject, error)
	// GetInstance Public instance information
	// (GET /instance)
	GetInstance(ctx context.Context, request GetInstanceRequestObject) (GetInstanceResponseObject, error)
	// GetJob Status of a background job you started (admins can see any)
	// (GET /jobs/{jobId})
	GetJob(ctx context.Context, request GetJobRequestObject) (GetJobResponseObject, error)
	// ListLibrary My library (own uploads ∪ distributions, minus removed/hidden/filtered/taken down)
	// (GET /library)
	ListLibrary(ctx context.Context, request ListLibraryRequestObject) (ListLibraryResponseObject, error)
	// ListLibraryFacets Series, authors, narrators or tags in my library, with book counts
	// (GET /library/facets)
	ListLibraryFacets(ctx context.Context, request ListLibraryFacetsRequestObject) (ListLibraryFacetsResponseObject, error)
	// GetMe The current user
	// (GET /me)
	GetMe(ctx context.Context, request GetMeRequestObject) (GetMeResponseObject, error)
	// ListBookmarks My bookmarks (optionally for one book)
	// (GET /me/bookmarks)
	ListBookmarks(ctx context.Context, request ListBookmarksRequestObject) (ListBookmarksResponseObject, error)
	// CreateBookmark Add a bookmark
	// (POST /me/bookmarks)
	CreateBookmark(ctx context.Context, request CreateBookmarkRequestObject) (CreateBookmarkResponseObject, error)
	// DeleteBookmark Delete a bookmark (leaves a tombstone for other devices)
	// (DELETE /me/bookmarks/{bookmarkId})
	DeleteBookmark(ctx context.Context, request DeleteBookmarkRequestObject) (DeleteBookmarkResponseObject, error)
	// UpdateBookmark Edit a bookmark (last write wins by client_ts)
	// (PATCH /me/bookmarks/{bookmarkId})
	UpdateBookmark(ctx context.Context, request UpdateBookmarkRequestObject) (UpdateBookmarkResponseObject, error)
	// ListCollections My collections
	// (GET /me/collections)
	ListCollections(ctx context.Context, request ListCollectionsRequestObject) (ListCollectionsResponseObject, error)
	// CreateCollection Create a collection
	// (POST /me/collections)
	CreateCollection(ctx context.Context, request CreateCollectionRequestObject) (CreateCollectionResponseObject, error)
	// DeleteCollection Delete a collection (books are not affected)
	// (DELETE /me/collections/{collectionId})
	DeleteCollection(ctx context.Context, request DeleteCollectionRequestObject) (DeleteCollectionResponseObject, error)
	// UpdateCollection Rename or describe a collection (last write wins by client_ts)
	// (PATCH /me/collections/{collectionId})
	UpdateCollection(ctx context.Context, request UpdateCollectionRequestObject) (UpdateCollectionResponseObject, error)
	// RemoveFromCollection Remove a book from a collection
	// (DELETE /me/collections/{collectionId}/books/{bookId})
	RemoveFromCollection(ctx context.Context, request RemoveFromCollectionRequestObject) (RemoveFromCollectionResponseObject, error)
	// AddToCollection Add a book to a collection
	// (PUT /me/collections/{collectionId}/books/{bookId})
	AddToCollection(ctx context.Context, request AddToCollectionRequestObject) (AddToCollectionResponseObject, error)
	// RemoveFromMyLibrary Remove a book from my view (restorable for 30 days; master copy is kept)
	// (DELETE /me/library/{bookId})
	RemoveFromMyLibrary(ctx context.Context, request RemoveFromMyLibraryRequestObject) (RemoveFromMyLibraryResponseObject, error)
	// HideInMyLibrary Archive (hide) a book in my library
	// (POST /me/library/{bookId}/hide)
	HideInMyLibrary(ctx context.Context, request HideInMyLibraryRequestObject) (HideInMyLibraryResponseObject, error)
	// RestoreToMyLibrary Restore a book from "Recently removed", or un-archive it
	// (POST /me/library/{bookId}/restore)
	RestoreToMyLibrary(ctx context.Context, request RestoreToMyLibraryRequestObject) (RestoreToMyLibraryResponseObject, error)
	// GetProgress My stored progress for a book
	// (GET /me/progress/{bookId})
	GetProgress(ctx context.Context, request GetProgressRequestObject) (GetProgressResponseObject, error)
	// PutProgress Report playback position
	// (PUT /me/progress/{bookId})
	PutProgress(ctx context.Context, request PutProgressRequestObject) (PutProgressResponseObject, error)
	// ListMySessions My device sessions
	// (GET /me/sessions)
	ListMySessions(ctx context.Context, request ListMySessionsRequestObject) (ListMySessionsResponseObject, error)
	// RevokeMySession Revoke one of my sessions
	// (DELETE /me/sessions/{sessionId})
	RevokeMySession(ctx context.Context, request RevokeMySessionRequestObject) (RevokeMySessionResponseObject, error)
	// GetSyncDelta Everything that changed for me since a cursor
	// (GET /me/sync)
	GetSyncDelta(ctx context.Context, request GetSyncDeltaRequestObject) (GetSyncDeltaResponseObject, error)
	// ListMyUploads My recent uploads and their processing status
	// (GET /me/uploads)
	ListMyUploads(ctx context.Context, request ListMyUploadsRequestObject) (ListMyUploadsResponseObject, error)
	// GetNarrator Narrator page (books visible to me)
	// (GET /narrators/{personId})
	GetNarrator(ctx context.Context, request GetNarratorRequestObject) (GetNarratorResponseObject, error)
	// GetSeries Series page (books in order, visible to me)
	// (GET /series/{seriesId})
	GetSeries(ctx context.Context, request GetSeriesRequestObject) (GetSeriesResponseObject, error)
	// CompleteSetup Finish the wizard (creates the admin, stores settings, switches the server to normal mode)
	// (POST /setup/complete)
	CompleteSetup(ctx context.Context, request CompleteSetupRequestObject) (CompleteSetupResponseObject, error)
	// TestSetupDatabase Check that a database can be opened
	// (POST /setup/database/test)
	TestSetupDatabase(ctx context.Context, request TestSetupDatabaseRequestObject) (TestSetupDatabaseResponseObject, error)
	// TestSetupLibrary Check the library path exists and is writable (warns if empty)
	// (POST /setup/library/test)
	TestSetupLibrary(ctx context.Context, request TestSetupLibraryRequestObject) (TestSetupLibraryResponseObject, error)
	// TestSetupSmtp Send a test email with the given SMTP settings
	// (POST /setup/smtp/test)
	TestSetupSmtp(ctx context.Context, request TestSetupSmtpRequestObject) (TestSetupSmtpResponseObject, error)
	// GetSetupStatus Whether the first-run wizard still needs to run
	// (GET /setup/status)
	GetSetupStatus(ctx context.Context, request GetSetupStatusRequestObject) (GetSetupStatusResponseObject, error)
	// CreateSetupTotp Generate the first admin's TOTP secret (enrollment is mandatory)
	// (POST /setup/totp)
	CreateSetupTotp(ctx context.Context, request CreateSetupTotpRequestObject) (CreateSetupTotpResponseObject, error)
	// GetHlsPlaylist Low-bitrate HLS playlist for the whole book (generated on demand)
	// (GET /stream/{bookId}/hls/{profile}/index.m3u8)
	GetHlsPlaylist(ctx context.Context, request GetHlsPlaylistRequestObject) (GetHlsPlaylistResponseObject, error)
	// GetHlsSegment One 10 s HLS segment
	// (GET /stream/{bookId}/hls/{profile}/{segment})
	GetHlsSegment(ctx context.Context, request GetHlsSegmentRequestObject) (GetHlsSegmentResponseObject, error)
}

type StrictHandlerFunc func(ctx context.Context, w http.ResponseWriter, r *http.Request, request any) (any, error)
type StrictMiddlewareFunc func(f StrictHandlerFunc, operationID string) StrictHandlerFunc

type StrictHTTPServerOptions struct {
	RequestErrorHandlerFunc  func(w http.ResponseWriter, r *http.Request, err error)
	ResponseErrorHandlerFunc func(w http.ResponseWriter, r *http.Request, err error)
}

func NewStrictHandler(ssi StrictServerInterface, middlewares []StrictMiddlewareFunc) ServerInterface {
	return &strictHandler{ssi: ssi, middlewares: middlewares, options: StrictHTTPServerOptions{
		RequestErrorHandlerFunc: func(w http.ResponseWriter, r *http.Request, err error) {
			http.Error(w, err.Error(), http.StatusBadRequest)
		},
		ResponseErrorHandlerFunc: func(w http.ResponseWriter, r *http.Request, err error) {
			http.Error(w, err.Error(), http.StatusInternalServerError)
		},
	}}
}

func NewStrictHandlerWithOptions(ssi StrictServerInterface, middlewares []StrictMiddlewareFunc, options StrictHTTPServerOptions) ServerInterface {
	if options.RequestErrorHandlerFunc == nil {
		options.RequestErrorHandlerFunc = func(w http.ResponseWriter, r *http.Request, err error) {
			http.Error(w, err.Error(), http.StatusBadRequest)
		}
	}
	if options.ResponseErrorHandlerFunc == nil {
		options.ResponseErrorHandlerFunc = func(w http.ResponseWriter, r *http.Request, err error) {
			http.Error(w, err.Error(), http.StatusInternalServerError)
		}
	}
	return &strictHandler{ssi: ssi, middlewares: middlewares, options: options}
}

type strictHandler struct {
	ssi         StrictServerInterface
	middlewares []StrictMiddlewareFunc
	options     StrictHTTPServerOptions
}

